; Generated by tools/nes_sfx2smps.py from smb1-disasm-master (SMB1 CastleMusic) - do not edit by hand.
; One 480-frame pass at one tick per frame (tempo $FF), looping back to the start
; where SMB1's EndOfMusicData restarts it. The S2 driver skips one tick every 256
; frames (tempo accumulator), so it runs 0.39% slower than SMB1: a one-frame hold
; about every 4.3 seconds. The song is stored uncompressed.
MarioCastle_Header:
	smpsHeaderStartSong 2
	smpsHeaderVoiceNull
	smpsHeaderChan      $01, $03
	smpsHeaderTempo     $01, $FF

	smpsHeaderDAC       MarioCastle_DAC
	smpsHeaderPSG       MarioCastle_PSG1,	$00, $03, $00, $00
	smpsHeaderPSG       MarioCastle_PSG2,	$00, $03, $00, $00
	smpsHeaderPSG       MarioCastle_PSG3,	$00, $02, $00, $00

; DAC Data (none)
MarioCastle_DAC:
	smpsStop

